#pragma once
#include "ksMidiFileEventTask.h"
#include "ksMidiFileTimeService.h"
#include <array>
#include <optional>
#include <stdexcept>
#include <type_traits>
namespace ks {
// Owns event/meta/VLQ/tempo continuations. Decode is a typed native child
// request serviced by the enclosing graph, never a legacy call or raw PC.
// The returned record binding is subsequently dereferenced by Mono ArpDelay;
// this single data operand must survive partial bytes and count restoration.
class MidiFileEventCoordinator final {
public:
 using Kind=MidiFileEventTask::Kind;using OutcomeHandle=uint32_t;static constexpr OutcomeHandle NoOutcome=~0u;
 enum class Component{Event,Time};enum class Request{None,Decode};enum class Notice{Policy,TimeComplete};
 struct Noop{template<class...T>void operator()(T&&...)const noexcept{}};
 struct Input{uint32_t stream=0;uint8_t byte=0,activation=0;uint32_t record=0;};struct ChildInput{uint8_t byte=0,activation=0;uint32_t dataBinding=0;};
 struct DecodeResult{OutcomeHandle outcome=NoOutcome;bool activationKnown=false;uint8_t activation=0;bool expressionKnown=false;uint32_t expressionSource=0,expressionSourceMask=0;bool dataBindingKnown=false;uint32_t dataBinding=0;};struct Effect{bool read=false,write=false;};
 struct Result{uint32_t stream=0,tempo=0,remaining=0,record=0;uint8_t byte=0,metaType=0,descriptor=0,activation=0;bool expressionKnown=false;uint32_t expressionSource=0,expressionSourceMask=0;OutcomeHandle lastDecode=NoOutcome;uint64_t decodeCalls=0;};
 explicit MidiFileEventCoordinator(Kind k):MidiFileEventCoordinator(k,Input{}){}
 MidiFileEventCoordinator(Kind k,Input i):kind_(k),input_(i){result_.activation=i.activation;result_.record=i.record;push(k,i);}
 Kind kind()const{return kind_;}const Input&input()const{return input_;}const Result&result()const{return result_;}const MidiFileTimeService*timeOutcome()const{return time_?&*time_:nullptr;}const Effect&effect()const{return effect_;}Component component()const{return component_;}Request request()const{return request_;}const ChildInput&childInput()const{return child_;}bool complete()const{return !depth_;}bool critical()const{return false;}unsigned priority()const{return 0;}
 bool resumeDecode(OutcomeHandle h){return resumeDecode(DecodeResult{h});}
 bool resumeDecode(DecodeResult r){if(request_!=Request::Decode)return false;result_.lastDecode=r.outcome;if(r.activationKnown)result_.activation=r.activation;if(r.dataBindingKnown)result_.record=r.dataBinding;const auto mask=r.expressionKnown?~0u:r.expressionSourceMask;if(mask){result_.expressionSource=(result_.expressionSource&~mask)|(r.expressionSource&mask);result_.expressionSourceMask|=mask;result_.expressionKnown=result_.expressionSourceMask==~0u;}++result_.decodeCalls;request_=Request::None;current().task.resumeChild();return true;}
 template<class T>const T*task()const{if constexpr(std::is_same_v<T,MidiFileEventTask>)return component_==Component::Event&&depth_?&current().task:nullptr;else if constexpr(std::is_same_v<T,MidiFileTimeService>)return component_==Component::Time?&*time_:nullptr;else return component_==Component::Time?time_->template task<T>():nullptr;}
 unsigned nextClocks(int previous=-1,int previousRead=-1)const{if(complete()||request_!=Request::None)return 0;if(component_==Component::Time)return time_->nextClocks(previous,previousRead);return current().task.nextClocks(busCost(current().task,previous));}
 template<class R,class W,class Resolver>unsigned advanceBefore(unsigned budget,R&&read,W&&write,Resolver&&resolver,int previous=-1,int previousRead=-1){Noop observer;return advanceObservedBefore(budget,read,write,resolver,observer,previous,previousRead);}
 template<class R,class W,class Resolver,class Observer>unsigned advanceObservedBefore(unsigned budget,R&&read,W&&write,Resolver&&resolver,Observer&&observer,int previous=-1,int previousRead=-1){const auto cost=nextClocks(previous,previousRead);if(!cost||cost>budget)return 0;effect_={};
 if(component_==Component::Time){time_->advanceBefore(cost,read,write,previous,previousRead);effect_={time_->effect().read,time_->effect().write};if(time_->complete()){auto&t=current().task;notify(observer,Notice::TimeComplete,t.stage(),t);if(t.child()==MidiFileEventTask::Child::Vlq){t.resumeVlq(time_->summary().value,time_->summary().stream);result_.expressionKnown=true;result_.expressionSourceMask=~0u;result_.expressionSource=time_->summary().value;}else {result_.record=time_->input().tempo>>4;t.resumeChild();}component_=Component::Event;}return cost;}
 using T=MidiFileEventTask;using S=T::Stage;auto&f=current();auto&t=f.task;const auto stage=t.stage();
 const auto byte=[&](uint32_t raw,unsigned back=0){if(!MidiFileTimeService::readable(raw,1))throw std::logic_error("Unsupported MIDI-file event byte span");return uint8_t(read(raw&0xffffff,cost-back));};
 t.advanceBefore(cost,[&](S q)->uint32_t{switch(q){case S::EventRead:case S::EventReadData:case S::MetaRead:case S::MetaReadSkip:case S::TempoReadLength:case S::TempoReadHigh:case S::TempoReadMiddle:case S::TempoReadLow:case S::ContinueRead:{const auto v=byte(t.stream(),2);f.lastRead=v;return v;}case S::EventReadStatusCount:case S::EventReadDataCount:return byte(0x15c1d);case S::MetaReadCandidate:{const auto v=byte(0x11a3e + 6*t.descriptor());result_.record=(result_.record&0xffff00ffu)|(uint32_t(v)<<8);return v;}case S::MetaReadHandler:{uint32_t raw=0;for(unsigned n=0;n<4;++n)raw=(raw<<8)|byte(0x11a40+6*t.descriptor()+n,3*((3-n)/2));result_.record=raw;f.handler=resolver.fileMeta(t.descriptor(),t.metaType(),raw);if(f.handler!=Kind::Skip&&f.handler!=Kind::Tempo&&f.handler!=Kind::End)throw std::logic_error("Unsupported authenticated MIDI-file meta action");return raw;}default:throw std::logic_error("Unknown MIDI-file event observation");}},[&](S q,uint32_t v){if(q!=S::EndPublish)throw std::logic_error("Unknown MIDI-file event publication");write(0x17328,uint8_t(v),cost);},[&](S){return busCost(t,previous);});
 switch(stage){case S::EventRetainCount:case S::ContinueRetainCount:case S::SendRetainStream:effect_.write=true;break;case S::EventReleaseCount:case S::ContinueReleaseCount:case S::SendReleaseStream:case S::EventFinish:case S::MetaFinish:case S::MetaHandlerFinish:case S::SkipFinish:case S::TempoFinish:case S::EndFinish:case S::ContinueFinish:case S::SendFinish:effect_.read=true;break;default:break;}
 switch(stage){case S::EventRead:case S::EventReadData:case S::StartStatus:case S::ContinueRead:result_.record=(result_.record&0xffffff00u)|t.byte();break;case S::MetaRead:case S::MetaReadSkip:case S::TempoReadLength:case S::TempoReadHigh:case S::TempoReadLow:result_.record=(result_.record&0xffffff00u)|f.lastRead;break;case S::TempoReadMiddle:result_.record=(result_.record&0xffff00ffu)|(uint32_t(f.lastRead)<<8);break;case S::TempoNormalize:result_.record&=255;break;case S::TempoPositionHigh:result_.record<<=16;break;case S::MetaClearSkip:result_.record=0;break;case S::EndClear:result_.record&=0xffffff00u;break;case S::EventReadStatusCount:case S::EventReadDataCount:case S::EventTickCount:result_.record=(result_.record&0xffffff00u)|uint8_t(t.remaining());break;case S::EventRetainCount:f.countPrefix=uint8_t(result_.record>>8);break;case S::EventReleaseCount:result_.record=(result_.record&0xffff0000u)|(uint32_t(f.countPrefix)<<8)|uint8_t(t.remaining());break;default:break;}
 if(stage==S::ContinueReleaseCount||stage==S::ContinueTick){result_.expressionKnown=true;result_.expressionSourceMask=~0u;result_.expressionSource=t.remaining();}
 notify(observer,Notice::Policy,stage,t);
 if(t.handoff()){const auto route=t.route();const Input i{t.stream(),t.byte(),result_.activation,result_.record};f.task=T(route==T::Route::Meta?Kind::Meta:route==T::Route::Start?Kind::Start:Kind::Continue,i.stream,i.byte);}
 else if(t.awaitingChild()){effect_.write=true;const Input i{t.stream(),t.byte(),result_.activation,result_.record};switch(t.child()){case T::Child::Send:push(Kind::Send,i);break;case T::Child::Meta:push(f.handler,i);break;case T::Child::Vlq:time_.emplace(MidiFileTimeService::Kind::Vlq,MidiFileTimeService::Input{i.stream,0,0});component_=Component::Time;break;case T::Child::Tempo:time_.emplace(MidiFileTimeService::Kind::Tempo,MidiFileTimeService::Input{i.stream,t.tempo(),0});component_=Component::Time;break;case T::Child::Decode:child_={t.byte(),result_.activation,result_.record};request_=Request::Decode;break;default:throw std::logic_error("Unclosed MIDI-file event child");}}
 else if(t.complete()){const auto stream=t.stream();const auto tempo=t.tempo();const auto remaining=t.remaining();const auto last=t.byte();const auto meta=t.metaType(),descriptor=t.descriptor();--depth_;if(depth_){auto&p=current().task;if(p.child()==T::Child::Meta)p.resumeMeta(stream);else p.resumeChild();}else {result_.stream=stream;result_.tempo=tempo;result_.remaining=remaining;result_.byte=last;result_.metaType=meta;result_.descriptor=descriptor;}}
 return cost;
 }
private:
 template<class O>void notify(O&observer,Notice notice,MidiFileEventTask::Stage stage,const MidiFileEventTask&t)const{static_assert(std::is_void_v<decltype(observer(notice,stage,*this,t))>,"File observer must return void");observer(notice,stage,*this,t);}
 struct Frame{MidiFileEventTask task;Kind handler=Kind::Skip;uint8_t lastRead=0,countPrefix=0;Frame(Kind k,Input i):task(k,i.stream,i.byte){}};
 Frame&current(){return *frames_[depth_-1];}const Frame&current()const{return *frames_[depth_-1];}
 void push(Kind k,Input i){if(depth_==frames_.size())throw std::logic_error("MIDI-file event depth exceeded");frames_[depth_++].emplace(k,i);component_=Component::Event;}
 static unsigned busCost(const MidiFileEventTask&t,int previous){using S=MidiFileEventTask::Stage;switch(t.stage()){case S::EventRead:case S::EventReadData:case S::MetaRead:case S::MetaReadSkip:case S::TempoReadLength:case S::TempoReadHigh:case S::TempoReadMiddle:case S::TempoReadLow:case S::ContinueRead:case S::EventReadStatusCount:case S::EventReadDataCount:case S::MetaReadCandidate:return 3;case S::MetaReadHandler:return 6;case S::EndPublish:return !(previous&1)&&0x17328u==(uint32_t(previous)|1u)?0:3;default:return 0;}}
 Kind kind_;Input input_;Result result_{};Effect effect_{};Component component_=Component::Event;Request request_=Request::None;ChildInput child_{};unsigned depth_=0;std::array<std::optional<Frame>,3>frames_{};std::optional<MidiFileTimeService>time_;
};
}
